/// Banco de evaluaciones bíblicas y generadores de preguntas.
/// Separado de main.dart para facilitar su mantenimiento y revisión doctrinal.

class QuizQuestion {
  final String question;
  final List<String> options;
  final int correctIndex;
  final String explanation;
  final String references;

  const QuizQuestion({
    required this.question,
    required this.options,
    required this.correctIndex,
    required this.explanation,
    required this.references,
  });
}

String _normalizedQuestionKey(String value) => value
    .toLowerCase()
    .replaceAll(RegExp(r'[áàä]'), 'a')
    .replaceAll(RegExp(r'[éèë]'), 'e')
    .replaceAll(RegExp(r'[íìï]'), 'i')
    .replaceAll(RegExp(r'[óòö]'), 'o')
    .replaceAll(RegExp(r'[úùü]'), 'u')
    .replaceAll('ñ', 'n')
    .replaceAll(RegExp(r'[^a-z0-9]'), '');

List<QuizQuestion> _uniqueQuestions(Iterable<QuizQuestion> questions) {
  final seen = <String>{};
  return questions.where((question) {
    final key = _normalizedQuestionKey(question.question);
    return key.isNotEmpty && seen.add(key);
  }).toList();
}

List<QuizQuestion> _completeQuestionSet(
  Iterable<QuizQuestion> preferred,
  Iterable<QuizQuestion> supplemental,
) {
  final unique = _uniqueQuestions([...preferred, ...supplemental]);
  return unique.take(20).toList();
}

class QuizPack {
  final String title;
  final String description;
  final List<QuizQuestion> questions;
  final String difficulty;
  final String source;

  const QuizPack({
    required this.title,
    required this.description,
    required this.questions,
    this.difficulty = 'Intermedio',
    this.source = 'Estudios bíblicos',
  });
}

